import{j as t,D as r}from"./index-CznQyCGL.js";import{E as l}from"./EmptyState-BwqazlVm.js";import{T as h}from"./TheoryCard-DcLfnoi6.js";import"./CardDetailContent-BOucGS3M.js";import"./Tag-By3c3N1R.js";function c({date:e}){const i=new Date(`${e}T00:00:00`),a=new Intl.DateTimeFormat("en-US",{month:"long"}).format(i).toUpperCase(),s=new Intl.DateTimeFormat("en-US",{day:"2-digit"}).format(i),o=new Intl.DateTimeFormat("en-US",{weekday:"long"}).format(i),n=new Intl.DateTimeFormat("en-US",{year:"numeric"}).format(i);return t.jsxs("section",{className:"date-header",children:[t.jsxs("div",{className:"date-header__binding","aria-hidden":"true",children:[t.jsx("span",{}),t.jsx("span",{})]}),t.jsx("p",{className:"date-header__month",children:a}),t.jsx("strong",{className:"date-header__day",children:s}),t.jsxs("div",{className:"date-header__meta",children:[t.jsx("span",{children:o}),t.jsx("span",{children:n})]}),t.jsxs("div",{className:"date-header__divider","aria-hidden":"true",children:[t.jsx("span",{}),t.jsx("b",{children:"✦"}),t.jsx("span",{})]})]})}function u(){return t.jsxs("section",{className:"sister-project-card","aria-labelledby":"daily-compass-title",children:[t.jsxs("div",{className:"sister-project-content",children:[t.jsx("p",{className:"sister-project-label",children:"Sister Project｜姊妹项目"}),t.jsx("h2",{id:"daily-compass-title",children:"The Daily Compass｜每日罗盘"}),t.jsx("p",{className:"sister-project-description",children:"A bilingual daily briefing for global news, culture, AI, finance, and social change."}),t.jsx("p",{className:"sister-project-description sister-project-description-zh",children:"一份用于理解全球资讯、文化、AI、金融与社会变化的双语每日小报。"}),t.jsx("p",{className:"sister-project-note",children:"看今天的世界正在发生什么。Read the world as it changes."}),t.jsx("a",{className:"sister-project-button",href:r,target:"_blank",rel:"noopener noreferrer","aria-label":"Open The Daily Compass in a new tab",children:"Open Daily Compass｜打开每日罗盘"})]}),t.jsx("div",{className:"sister-project-symbol","aria-hidden":"true",children:"✦"})]})}const d=[{id:"2026-07-01-mary-wollstonecraft",date:"2026-07-01",type:"thinker",personId:"wollstonecraft-1792",title:"Mary Wollstonecraft",titleZh:"玛丽·沃斯通克拉夫特",focusTitle:"Education Against Dependence",focusTitleZh:"反对依附的教育",summaryEn:"Mary Wollstonecraft argued that women were not naturally weak or frivolous. They were made so by an education that trained them to please, depend, and seek power indirectly.",summaryZh:"玛丽·沃斯通克拉夫特指出，女性并非天生软弱或轻浮。她们之所以如此，是因为社会教育她们取悦他人、依附他人，并只能以间接方式获得权力。",tags:["education","reason","dependence","virtue","women’s rights","citizenship","false refinement"],status:"published"},{id:"2026-07-02-mary-shelley",date:"2026-07-02",type:"writer",title:"Mary Shelley",titleZh:"玛丽·雪莱",years:"1797–1851",role:"Writer｜作家",focusTitle:"The Mother of Science Fiction",focusTitleZh:"科幻小说之母",summaryEn:"Mary Shelley’s Frankenstein is not only a story of scientific creation. It is also a story about abandonment, social exclusion, and the violence that grows when a living being is denied care.",summaryZh:"玛丽·雪莱的《弗兰肯斯坦》并不只是关于科学创造的故事。它也是关于遗弃、社会排斥，以及一个生命在被拒绝照护后如何走向暴力的故事。",tags:["science fiction","creation","abandonment","monster","care","responsibility","outsider","female gothic"],status:"published"},{id:"2026-07-03-jane-eyre",date:"2026-07-03",type:"text",title:"Jane Eyre",titleZh:"简·爱",creator:"Charlotte Brontë",creatorZh:"夏洛蒂·勃朗特",focusTitle:"A Free Human Being",focusTitleZh:"一个自由的人",summaryEn:"Jane Eyre gives voice to a woman who is poor, plain, socially powerless, and yet refuses to be treated as an object without soul, feeling, or will.",summaryZh:"《简·爱》让一个贫穷、平凡、缺乏社会权力的女性发出声音：她拒绝被当作没有灵魂、没有情感、没有意志的物品。",tags:["voice","dignity","will","self-respect","feminist fiction","independence","governess"],status:"published"},{id:"2026-07-04-wuthering-heights",date:"2026-07-04",type:"text",title:"Wuthering Heights",titleZh:"《呼啸山庄》",years:"1818–1848",role:"Text｜文本",creator:"Emily Brontë",creatorZh:"艾米莉·勃朗特",focusTitle:"Wildness, Love, and the Unsettled Self",focusTitleZh:"荒原、爱与不安的自我",summaryEn:"Wuthering Heights is more than a tragic romance. It is a novel about wild feeling, social constraint, and a woman’s divided sense of self within family, class, and marriage.",summaryZh:"《呼啸山庄》不只是悲剧爱情。它也是一部关于强烈情感、社会约束，以及女性在家庭、阶级与婚姻中如何感到自我分裂的小说。",tags:["gothic","desire","class","wildness","selfhood","Catherine Earnshaw","feminist reading"],status:"published"},{id:"2026-07-05-jane-austen",date:"2026-07-05",type:"writer",title:"Jane Austen",titleZh:"简·奥斯汀",years:"1775–1817",focusTitle:"Desire in the Material World",focusTitleZh:"物质世界中的欲望",summaryEn:"Jane Austen rarely makes sex visible, but desire is everywhere in her novels: in houses, incomes, gifts, letters, clothes, reputations, and the fragile material conditions under which women choose.",summaryZh:"简·奥斯汀很少直接呈现性，但欲望并没有消失。它存在于房屋、收入、礼物、信件、衣服、名誉，以及女性作出选择时脆弱的物质条件之中。",tags:["material culture","desire","marriage","objects","judgment","sexual silence","property"],status:"published"},{id:"2026-07-06-the-madwoman-in-the-attic",date:"2026-07-06",type:"criticism",title:"The Madwoman in the Attic",titleZh:"阁楼上的疯女人",creator:"Sandra M. Gilbert & Susan Gubar",focusTitle:"Angel, Monster, and the Woman Writer",focusTitleZh:"天使、怪物与女性写作者",summaryEn:"Gilbert and Gubar argue that patriarchal literary history often traps women between two images: the angelic, obedient woman and the monstrous, rebellious woman.",summaryZh:"Gilbert 与 Gubar 指出，父权文学传统常常把女性困在两种形象之间：顺从、纯洁的“天使”，以及危险、反叛的“怪物”。",tags:["literary criticism","angel","monster","madwoman","Jane Eyre","Bertha Mason","feminist reading"],status:"published"},{id:"2026-07-07-qiu-jin",date:"2026-07-07",type:"writer",title:"Qiu Jin",titleZh:"秋瑾",years:"1875–1907",role:"Writer｜作家 / Revolutionary｜革命者",focusTitle:"A Woman Who Refused the Dark",focusTitleZh:"拒绝黑暗的女子",summaryEn:"Qiu Jin wrote as a poet, feminist, and revolutionary. Her work turns women’s awakening into a public language of freedom, education, courage, and collective self-rescue.",summaryZh:"秋瑾既是诗人、女性主义者，也是革命者。她的写作把女性觉醒转化为一种公共语言：关于自由、教育、勇气，也关于女性彼此唤醒、共同自救。",tags:["women’s awakening","freedom","education","revolution","poetry","courage","sisterhood"],status:"published"},{id:"2026-07-08-orlando",date:"2026-07-08",type:"text",title:"Orlando",titleZh:"《奥兰多》",years:"1882–1941",role:"Text｜文本 / Novel｜小说",creator:"Virginia Woolf",creatorZh:"弗吉尼亚·伍尔夫",focusTitle:"A Biography for a Woman Who Could Not Be Contained",focusTitleZh:"一部写给无法被容纳之人的传记",summaryEn:"Virginia Woolf turns biography inside out: at a time when public life and literary history often centered men, Orlando gives a long, playful, impossible life to a figure who crosses gender, centuries, bodies, and histories.",summaryZh:"弗吉尼亚·伍尔夫把传记翻转过来：在公共生活与文学史长期以男性为中心的时代，《奥兰多》把一个漫长、戏谑、不可思议的一生，写给了一个跨越性别、世纪、身体与历史的人。",tags:["biography","gender","women’s history","queer temporality","fiction","queer reading","literary history","Virginia Woolf"],status:"published"},{id:"2026-07-09-a-room-of-ones-own",date:"2026-07-09",type:"text",title:"A Room of One’s Own",titleZh:"《一间自己的房间》",years:"1882–1941",role:"Text｜文本",creator:"Virginia Woolf",creatorZh:"弗吉尼亚·伍尔夫",focusTitle:"A Room of Her Own",focusTitleZh:"一个属于她自己的空间",summaryEn:"Virginia Woolf’s A Room of One’s Own is not only about having a physical room. It is a thought experiment about what happens when women’s intelligence is constantly interrupted by poverty, domestic responsibility, emotional labour, and the expectation to care for others.",summaryZh:"弗吉尼亚·伍尔夫的《一间自己的房间》并不只是关于拥有一个房间。它是一场思想实验：当女性的智慧不断被贫困、家庭责任、情感劳动，以及照顾他人的期待打断时，会发生什么。",tags:["women’s writing","emotional labour","creativity","domestic work","feminist theory"],status:"published"},{id:"2026-07-10-wages-against-housework",date:"2026-07-10",type:"theory",personId:"federici-1975",title:"Wages Against Housework",titleZh:"《反对家务劳动》",years:"b. 1942",role:"Theory｜理论 / Essay｜文章",creator:"Silvia Federici",creatorZh:"西尔维娅·费代里奇",focusTitle:"To Name Love as Work",focusTitleZh:"把爱命名为劳动",summaryEn:"Silvia Federici argues that housework is not a natural expression of women’s love. It is unwaged labour that reproduces workers, families, and capitalism itself.",summaryZh:"Silvia Federici 指出，家务并不是女性之爱的自然表达。它是一种无偿劳动，生产并维持着工人、家庭，以及资本主义本身。",tags:["housework","unwaged labour","care","capitalism","feminist theory","social reproduction","emotional labour"],status:"published"},{id:"2026-07-13-a-womans-story",date:"2026-07-13",type:"text",title:"A Woman's Story",titleZh:"《一个女人的故事》",years:"b. 1940",role:"Text｜文本 / Memoir｜回忆录",creator:"Annie Ernaux",creatorZh:"安妮·埃尔诺",focusTitle:"The Woman Beyond the Mother",focusTitleZh:"母亲之外的那个女人",summaryEn:"Annie Ernaux writes about her mother not as a timeless symbol of motherhood, but as a woman shaped by labour, class, ambition, aging, and the desire to escape the life assigned to her.",summaryZh:"安妮·埃尔诺书写母亲，却没有把她变成一个永恒的母亲形象。她写的是一个被劳动、阶级、抱负、衰老与逃离命定生活的渴望共同塑造的女人。",tags:["motherhood","class","memory","social mobility","aging","women's history","working-class life"],status:"published"},{id:"2026-07-14-linda-nochlin",date:"2026-07-14",type:"criticism",title:"Why Have There Been No Great Women Artists?",titleZh:"《为什么没有伟大的女性艺术家？》",years:"1931–2017",role:"Criticism｜艺术史批评 / Essay｜文章",creator:"Linda Nochlin",creatorZh:"琳达·诺克林",focusTitle:"The Question Is the Institution",focusTitleZh:"问题不在女性，而在制度",summaryEn:"Linda Nochlin asks us to stop treating women’s absence from the canon as proof of insufficient talent. The real question is how education, institutions, professional training, patronage, and social expectations determined who was allowed to become a “great artist.”",summaryZh:"琳达·诺克林要求我们停止把女性在艺术史经典中的缺席，当作她们缺乏天赋的证明。真正的问题是：教育、制度、专业训练、赞助体系与社会期待，如何决定了谁能够成为所谓的“伟大艺术家”。",tags:["feminist art history","institutions","artistic education","genius","women artists","the nude","art canon","structural inequality"],status:"published"},{id:"2026-07-15-yoko-ono-cut-piece",date:"2026-07-15",type:"performance",personId:"ono-1964",title:"Cut Piece",titleZh:"《切片》",years:"b. 1933",role:"Performance｜行为艺术 / Conceptual Art｜观念艺术",creator:"Yoko Ono",creatorZh:"小野洋子",focusTitle:"What Will the Audience Take?",focusTitleZh:"观众会从她身上拿走什么？",summaryEn:"In Cut Piece, Yoko Ono sits silently while audience members approach with scissors and cut away parts of her clothing. The work does not simply expose the artist’s body; it exposes the choices, hesitation, restraint, and violence of the audience.",summaryZh:"在《切片》中，小野洋子沉默地坐着，观众依次拿起剪刀，剪下她身上的衣物。作品所暴露的不只是艺术家的身体，也包括观众的选择、犹豫、克制与暴力。",tags:["performance art","participation","vulnerability","violence","audience","body","consent","feminist art","Fluxus","conceptual art"],status:"published"},{id:"2026-07-16-judy-chicago-the-dinner-party",date:"2026-07-16",type:"installation",personId:"chicago-1979",title:"The Dinner Party",titleZh:"《晚宴》",years:"b. 1939",role:"Installation｜装置艺术 / Feminist Art｜女性主义艺术",creator:"Judy Chicago",creatorZh:"朱迪·芝加哥",focusTitle:"Who Gets a Seat at History’s Table?",focusTitleZh:"谁能在历史的餐桌上拥有一个席位？",summaryEn:"Judy Chicago’s The Dinner Party imagines women’s history as a monumental banquet. Around a triangular table, women who were forgotten, marginalized, or erased from dominant historical narratives are given a place, a name, and a seat at the table.",summaryZh:"朱迪·芝加哥的《晚宴》把女性历史想象成一场纪念碑式的宴会。在一张巨大的三角形餐桌旁，那些曾被主流历史遗忘、边缘化或抹去的女性，重新获得了位置、名字，以及属于自己的席位。",tags:["feminist art","women’s history","the canon","craft","memory","collective history","women’s work","domestic labour","historical erasure","feminist archive"],status:"published"},{id:"2026-07-17-meret-oppenheim-object",date:"2026-07-17",type:"sculpture",title:"Object",titleZh:"《物体》",years:"1913–1985",role:"Surrealism｜超现实主义 / Sculpture｜雕塑",creator:"Meret Oppenheim",creatorZh:"梅雷特·奥本海姆",focusTitle:"When Everyday Objects Refuse to Behave",focusTitleZh:"当日常物件拒绝服从日常",summaryEn:"Meret Oppenheim covered a teacup, saucer, and spoon with fur, transforming an ordinary object of comfort into something intimate, absurd, and unsettling. The work asks what happens when familiar things no longer behave as we expect them to.",summaryZh:"梅雷特·奥本海姆用皮毛覆盖了茶杯、茶托与茶匙，把一件与舒适和日常习惯有关的器具，变成了既亲密、荒诞又令人不安的物体。作品追问：当熟悉的事物不再按照我们的期待发挥作用，会发生什么？",tags:["surrealism","object","desire","discomfort","domesticity","transformation","touch","material","body","women artists","function","everyday life"],status:"published"},{id:"2026-07-18-olga-tokarczuk-flights",date:"2026-07-18",type:"novel",title:"Flights",titleZh:"《云游》",years:"b. 1962",role:"Novel｜小说 / Fragmentary Fiction｜碎片化叙事",creator:"Olga Tokarczuk",creatorZh:"奥尔加·托卡尔丘克",focusTitle:"Can We Ever Stay in One Place?",focusTitleZh:"我们真的能够停留在一个地方吗？",summaryEn:"In Flights, Olga Tokarczuk moves between airports, hotel rooms, maps, preserved bodies, lost travellers, and stories separated by centuries. Rather than treating travel as a route from one destination to another, the novel asks what constant movement does to memory, identity, and the body.",summaryZh:"在《云游》中，奥尔加·托卡尔丘克穿行于机场、旅馆、地图、被保存的身体、失踪的旅人，以及彼此相隔数百年的故事之间。小说并不把旅行理解为从一个目的地前往另一个目的地的路线，而是追问：持续移动会如何改变记忆、身份与身体？",tags:["movement","travel","body","fragments","maps","borders","identity","migration","anatomy","memory","displacement","belonging"],status:"published"},{id:"2026-07-19-chiharu-shiota-absence-embodied",date:"2026-07-19",type:"installation",title:"Absence Embodied",titleZh:"《缺席的实体》",years:"b. 1972",role:"Installation｜装置艺术",creator:"Chiharu Shiota",creatorZh:"盐田千春",focusTitle:"Can Absence Take Up Space?",focusTitleZh:"缺席也能占据空间吗？",summaryEn:"In Absence Embodied, Chiharu Shiota fills the gallery with a dense web of red wool, transforming empty space into something almost physical. Thread becomes blood, memory, distance, and human connection, while the casts of hands and feet suggest bodies that are no longer fully present.",summaryZh:"在《缺席的实体》中，盐田千春以密集的红色羊毛线填满展厅，将原本空无一物的空间变成一种近乎具有实体的存在。线既像血液，也像记忆、距离与人与人之间的联系；散落其中的手脚翻模，则暗示着那些已经无法完整出现的身体。",tags:["absence","memory","body","thread","connection","migration","displacement","belonging","family","blood","installation","traces","relationships","red thread"],image:"/images/chiharu-shiota-absence-embodied-agsa.png",imageCredit:"AGSA",status:"published"},{id:"2026-07-20-riane-eisler-the-chalice-and-the-blade",date:"2026-07-20",type:"novel",title:"The Chalice and the Blade",titleZh:"《圣杯与剑》",years:"b. 1931",role:"Book｜著作",creator:"Riane Eisler",creatorZh:"瑞安·艾斯勒",focusTitle:"Who Writes the Story of Civilization?",focusTitleZh:"谁定义了文明的故事？",summaryEn:"For centuries, history has often been told through conquest, rulers, war, and the rise and fall of empires. In The Chalice and the Blade, Riane Eisler asks whether human societies must always be organised through domination—or whether another way of living together is possible.",summaryZh:"几个世纪以来，历史常常被讲述为征服、统治者、战争，以及帝国兴衰的故事。在《圣杯与剑》中，瑞安·艾斯勒提出：人类社会是否必然建立在统治之上？我们是否可能以另一种方式共同生活？",sourceNote:"This entry is based primarily on the 1987 bibliographic record, the official HarperCollins book description, and Riane Eisler’s public explanations of the partnership–domination framework. The sections on prehistory are explicitly presented as Eisler’s interpretation rather than as uncontested archaeological fact. An unverified direct quotation from the earlier draft has been removed.｜本篇主要依据1987年初版书目信息、HarperCollins官方书籍介绍，以及瑞安·艾斯勒关于“伙伴体系—统治体系”的公开说明整理。有关史前社会的段落已明确写成艾斯勒的理论解释，而不是无争议的考古事实；原稿中无法确认出处的直接引文也已删除。",tags:["partnership","domination","feminism","archaeology","civilization","history","gender","equality","caregiving","social change","power","cooperation"],status:"published"},{id:"2026-07-21-sianne-ngai-our-aesthetic-categories",date:"2026-07-21",type:"essay",title:"Our Aesthetic Categories",titleZh:"《我们的审美范畴》",years:"Published 2010",role:"Essay｜论文",creator:"Sianne Ngai",creatorZh:"Sianne Ngai",focusTitle:"How Has Capitalism Changed Aesthetics?",focusTitleZh:"资本主义如何改变了审美？",summaryEn:"For centuries, aesthetics revolved around beauty and the sublime. Sianne Ngai argues that these are no longer the concepts through which we most often experience everyday life. Instead, contemporary culture is increasingly organised around three ordinary judgments: cute, interesting, and zany.",summaryZh:"几个世纪以来，美学始终围绕着“美”与“崇高”展开。Sianne Ngai认为，在当代生活中，我们真正不断使用的审美判断已经发生改变。今天，我们越来越通过三个普通的词理解世界：可爱（cute）、有趣（interesting）和疯癫（zany）。",sourceNote:"This entry is based on Sianne Ngai’s essay “Our Aesthetic Categories,” published in PMLA, Vol. 125, No. 4, October 2010, pp. 948–958.｜本篇依据 Sianne Ngai 发表于《PMLA》2010年10月第125卷第4期、948–958页的论文《Our Aesthetic Categories》整理。",tags:["aesthetics","cultural theory","literary criticism","capitalism","cute","interesting","zany","affect","labor","consumption","media","everyday life"],status:"published"},{id:"2026-07-22-annie-ernaux-simple-passion",date:"2026-07-22",type:"novel",personId:"annie-ernaux",title:"Simple Passion",titleZh:"《简单的激情》",years:"Published 1991",role:"Novel / Autofiction｜小说 / 自传体写作",author:"Annie Ernaux｜安妮·埃尔诺",focusTitle:"What Brings Us Closer to the World?",focusTitleZh:"是什么让我们更接近世界？",summaryEn:"Simple Passion begins with an affair, but its deepest subject is not romance. Annie Ernaux records what happens when one experience reorganises time, sharpens the body, suspends judgment, and makes life feel unusually intense. The person at its centre may disappear. What remains is a newly awakened capacity to enter the world.",summaryZh:"《简单的激情》从一段情事开始，但它最深层的主题并不是爱情。安妮·埃尔诺记录了一种经验如何重新组织时间、唤醒身体、悬置判断，并让生命变得异常强烈。处于经验中心的人或许会消失，留下来的，却是一种重新进入世界的能力。",highlightEn:"What changes us is not always the person or event itself, but the life that becomes possible through it.",highlightZh:"真正改变我们的，未必是某个人或某件事本身，而是我们通过它所抵达的那种生命状态。",tags:["passion","vitality","intensity","time","memory","body","attention","experience","vulnerability","connection","autofiction","women's writing"],status:"published"},{id:"2026-07-23-eva-illouz-why-love-hurts",date:"2026-07-23",type:"theory",title:"Why Love Hurts: A Sociological Explanation",titleZh:"《爱，为什么痛？》",years:"Published 2012",role:"Theory / Sociology｜理论 / 社会学",author:"Eva Illouz｜伊娃·易洛思",focusTitle:"Why Does Freedom Also Make Love Hurt?",focusTitleZh:"为什么自由也会让爱变得更痛？",summaryEn:"We often experience romantic suffering as evidence that something is wrong with us. We search our childhood, personality, appearance, and past decisions for an explanation. Eva Illouz asks us to look beyond the private self. The pain of modern love is also produced by the social conditions under which people desire, choose, compare, and commit to one another.",summaryZh:"我们常把爱情中的痛苦理解为自身出了问题。我们从童年、性格、外貌和过去的选择中寻找原因。伊娃·易洛思却邀请我们把目光移出私人自我：现代爱情的痛苦，也产生于人们学习欲望、选择、比较与承诺的社会条件之中。",highlightEn:"Love may feel entirely personal. Yet the conditions under which we love are social.",highlightZh:"爱情或许是一种极其私人的感受，但我们如何去爱，始终受到社会条件的塑造。",sourceNote:"This entry was rewritten and verified against Eva Illouz, Why Love Hurts: A Sociological Explanation, Polity Press, 2012. The chapter references follow the uploaded edition. Except for the explicitly marked verified passage, all sentences are editorial summaries rather than direct quotations.｜本篇依据伊娃·易洛思《爱，为什么痛？：一种社会学解释》2012年Polity版本重写并核实。章节标注依据上传版本。除明确标出的核实引文外，其余内容均为编辑性概括，并非作者原句。",tags:["love","sociology","romantic freedom","choice","recognition","commitment","emotional inequality","gender","capitalism","imagination"],status:"published"},{id:"2026-07-24-women-in-the-picture",date:"2026-07-24",type:"book",title:"Who Gets to Look?",titleZh:"谁拥有观看的权力？",role:"Art History / Feminist Criticism｜艺术史 / 女性主义批评",author:"Catherine McCormack｜凯瑟琳·麦考马克",focusTitle:"Who Gets to Look?",focusTitleZh:"谁拥有观看的权力？",summaryEn:"Pictures do more than represent women. They also teach us what kinds of women deserve admiration, sympathy, fear, or silence.",summaryZh:"图像不仅描绘女性。它们也教会我们：哪些女性值得赞美，哪些女性值得同情，哪些女性令人恐惧，又有哪些女性应该保持沉默。",highlightEn:"Every image teaches a way of seeing.",highlightZh:"每一幅图像，都在教会我们一种观看世界的方式。",sourceNote:"This entry is based on Catherine McCormack’s Women in the Picture: What Culture Does with Female Bodies.｜本篇依据 Catherine McCormack《画框中的女性》整理。",tags:["art history","representation","museums","looking","women","feminist criticism","visual culture","gender","power","images"],status:"published"},{id:"2026-07-25-rebecca-traister-good-and-mad",date:"2026-07-25",type:"theory",title:"Good and Mad: The Revolutionary Power of Women’s Anger",titleZh:"《好不愤怒：女性愤怒的革命力量》",years:"Published 2018",role:"Theory / Feminism｜理论 / 女性主义",author:"Rebecca Traister｜丽贝卡·特雷斯特",focusTitle:"Who Gets to Be Angry?",focusTitleZh:"谁有资格愤怒？",summaryEn:"Some emotions are treated as signs of authority. Others are treated as signs of instability. Rebecca Traister asks why anger has so often strengthened men’s authority while undermining women’s credibility. Rather than seeing women’s anger as a personal failing, she argues that it can reveal structures of inequality that have long been ignored.",summaryZh:"有些情绪会被理解为权威的象征，有些情绪却会被理解为失控的证据。丽贝卡·特雷斯特追问：为什么愤怒常常强化男性的权威，却削弱女性的可信度？她认为，女性的愤怒并不是一种个人缺陷，而是一种揭示长期不平等结构的力量。",highlightEn:"Anger does not always destroy relationships. Sometimes, it destroys silence.",highlightZh:"愤怒未必摧毁关系。它有时摧毁的是沉默。",tags:["anger","feminism","emotion","power","patriarchy","public life","collective action","gender","politics","social change"],status:"published"},{id:"2026-07-26-reading-the-romance",date:"2026-07-26",type:"book",title:"Reading the Romance: Women, Patriarchy, and Popular Literature",titleZh:"《阅读浪漫小说：女性、父权制和通俗文学》",years:"First published 1984｜初版于1984年",role:"Cultural Studies / Feminist Criticism｜文化研究 / 女性主义批评",author:"Janice A. Radway｜珍妮斯·A. 拉德威",focusTitle:"A Room Made of Reading",focusTitleZh:"一间由阅读构成的房间",summaryEn:"A woman opens a romance novel and, for a while, becomes unavailable to everyone around her. Janice A. Radway asks us to look beyond the stories inside these books and notice the act of reading itself: the privacy it creates, the demands it suspends, and the emotional care it offers to women who are usually expected to care for others.",summaryZh:"一个女人打开一本浪漫小说，并在一段时间里不再随时为身边的人待命。珍妮斯·A. 拉德威提醒我们，不应只关注书中的爱情故事，也要看见阅读行为本身：它创造的私人空间、它暂时中止的家庭要求，以及它给予那些总被期待照顾他人的女性的情感补给。",highlightEn:"Sometimes, reading is not an escape from life. It is a brief refusal to remain available to everyone.",highlightZh:"有时，阅读并不是逃离生活。它只是短暂地拒绝继续随时为所有人待命。",sourceNote:"This entry is based on Janice A. Radway, Reading the Romance: Women, Patriarchy, and Popular Literature. The Related Works section has been intentionally omitted.｜本篇依据珍妮斯·A. 拉德威《阅读浪漫小说：女性、父权制和通俗文学》整理，并按要求删除“相关作品”部分。",tags:["reading","romance","privacy","emotional care","patriarchy","popular culture"],status:"published"},{id:"2026-07-27-beautiful-world-where-are-you",date:"2026-07-27",type:"book",title:"Beautiful World, Where Are You",titleZh:"《美丽的世界，你在哪里》",role:"Novel / Contemporary Fiction｜小说 / 当代文学",author:"Sally Rooney｜萨莉·鲁尼",focusTitle:"Can Friendship Survive Unequal Lives?",focusTitleZh:"当生活不再平等，友谊还能继续吗？",summaryEn:"Alice and Eileen were once young women moving through the same world. Now their lives have begun to separate. Alice is a famous novelist living alone in an enormous house by the sea. Eileen works for a literary magazine in Dublin, living within the ordinary limits of wages, rent, work, and family. They still write to one another about love, politics, beauty, work, and the future—but money and success have changed what each of them can imagine. Their friendship does not exist outside class. It carries admiration, resentment, shame, tenderness, and the fear that one woman’s life has moved beyond the other’s reach. Yet they continue to write.",summaryZh:"艾莉丝与艾琳曾经是生活在同一个世界里的年轻女性。如今，她们的人生已经开始分离。艾莉丝成为知名小说家，独自住在海边一座巨大的房子里。艾琳则在都柏林的一本文学杂志工作，生活仍受到工资、房租、工作与家庭的日常限制。她们继续在邮件中讨论爱情、政治、美、工作与未来，但金钱和成功已经改变了她们能够想象的生活。她们的友谊并不位于阶级之外。羡慕、怨恨、羞耻、温柔，以及害怕对方已经走入自己无法抵达的生活，都存在于这段关系之中。但她们仍然继续写信。",highlightEn:"Friendship does not make two lives equal. It asks whether they can remain connected after they have become unequal.",highlightZh:"友谊不会让两种生活变得平等。它追问的是：当生活已经不再平等，我们是否仍能保持联系。",sourceNote:"以上为日历编辑性概括，并非原书引文。",tags:["female friendship","class inequality","money","houses","work","intimacy","desire","writing","success","contemporary fiction"],status:"published"},{id:"2026-07-28-conversations-with-friends",date:"2026-07-28",type:"novel",title:"Conversations with Friends",titleZh:"《聊天记录》",role:"Novel / Contemporary Fiction｜小说 / 当代文学",author:"Sally Rooney｜萨莉·鲁尼",focusTitle:"What Does Class Look Like in a Room Full of People?",focusTitleZh:"当人们聚在一起，阶级是什么样子？",summaryEn:"Frances and Bobbi are young, intelligent, and newly entering adult society. They perform poetry together, talk about politics, and know how to appear ironic, self-possessed, and difficult to impress. Then they meet Melissa and Nick. The older couple have a house, careers, cultural recognition, expensive objects, professional contacts, and the relaxed confidence of people who already belong to the world Frances and Bobbi are only beginning to enter. Sally Rooney rarely explains class through abstract statements. She lets it appear through a taxi destination, a bowl of ripe fruit, a glass conservatory, a holiday home, a dinner invitation, and the way a young woman rehearses the facial expressions that might make her seem charming.",summaryZh:"弗朗西丝与博比年轻、聪明，刚刚开始进入成年人的社会。她们一起表演诗歌，谈论政治，也懂得如何显得讽刺、冷静，仿佛不容易被任何事物打动。然后，她们认识了梅利莎与尼克。这对年长的夫妇拥有房屋、事业、文化声望、昂贵的物品、职业关系，以及一种属于“已经进入这个世界的人”的松弛自信。而弗朗西丝与博比，才刚刚站在这个世界的门口。萨莉·鲁尼很少用抽象论述解释阶级。她让阶级通过一个出租车目的地、一碗成熟的水果、一间玻璃暖房、一栋度假屋、一次晚餐邀请，以及年轻女孩为了显得迷人而预先练习的面部表情，慢慢显现出来。",highlightEn:"Class is not only what people own. It is how comfortably they know what to do.",highlightZh:"阶级不只是一个人拥有什么。它也体现在：一个人是否自然地知道该怎么做。",sourceNote:"以上为日历编辑性概括，并非原书引文。",tags:["class","social performance","young women","cultural capital","talent","conversation","houses","manners","intimacy","contemporary fiction"],status:"published"},{id:"2026-07-29-hilma-af-klint-paintings-for-the-future",date:"2026-07-29",type:"artist",title:"Paintings for the Future",titleZh:"《献给未来的绘画》",role:"Art / Abstraction / Spirituality｜艺术 / 抽象 / 灵性",author:"Hilma af Klint｜希尔玛·阿夫·克林特",focusTitle:"Who Enters History—and Who Only Makes It?",focusTitleZh:"谁进入历史，谁只是创造了历史？",summaryEn:"In 1906, Hilma af Klint began The Paintings for the Temple, a vast project that would eventually include 193 works. The paintings were filled with circles, spirals, flowers, letters, geometric structures, and luminous fields of colour. Many no longer represented the visible world in any conventional sense. Af Klint was not simply trying to invent a new artistic style. She believed painting could give form to realities that ordinary sight could not reach. Yet these works remained largely outside public view during her lifetime. For decades, the history of abstraction was written mainly around artists whose work had entered exhibitions, criticism, collections, and textbooks. Hilma af Klint’s paintings existed. But existence alone was not enough to make them part of history.",summaryZh:"1906年，希尔玛·阿夫·克林特开始创作《神殿绘画》。这是一项庞大的艺术计划，最终包含193件作品。画面中充满圆形、螺旋、花朵、字母、几何结构，以及明亮而流动的色彩。许多作品已经不再以传统方式描绘肉眼可见的世界。阿夫·克林特并不只是想发明一种新的艺术风格。她相信，绘画可以为普通视觉无法抵达的现实赋予形式。然而，这批作品在她生前基本没有进入公共视野。此后的几十年里，抽象艺术史主要围绕那些进入展览、评论、收藏与教科书的艺术家展开。希尔玛·阿夫·克林特的画一直存在。但仅仅存在，并不足以让它们进入历史。",highlightEn:"Making history and entering history are not always the same event.",highlightZh:"创造历史，与进入历史，并不总是同一件事。",sourceNote:"以上为日历编辑性概括，并非艺术家原话。",tags:["abstract art","women artists","spirituality","modernism","visibility","archives","institutions","art history","canon","the future"],status:"published"},{id:"2026-07-30-women-who-run-with-the-wolves",date:"2026-07-30",type:"book",title:"Women Who Run with the Wolves",titleZh:"《与狼同行的女人》",role:"Psychology / Myth / Feminine Instinct｜心理学 / 神话 / 女性本能",author:"Clarissa Pinkola Estés｜克拉丽莎·平科拉·埃斯蒂斯",focusTitle:"What Remains When a Woman Has Been Stripped Down to the Bones?",focusTitleZh:"当一个女人被剥夺到只剩骨头，还会留下些什么？",summaryEn:"Clarissa Pinkola Estés begins Women Who Run with the Wolves with a striking comparison: women and wolves have both been feared, misrepresented, driven away, and forced into narrower territories. The book calls the instinctive, intuitive, creative, and life-preserving force within women the Wild Woman. ‘Wild’ does not mean reckless or out of control. It means living according to a deeper integrity: sensing danger, protecting boundaries, creating, choosing, leaving, staying, and knowing when something must die so that something else can live. In the story of La Loba, an old woman wanders the desert collecting the bones of wolves. When she has assembled a complete skeleton, she sings over it. The bones grow flesh. The body begins to breathe. The wolf rises, runs, and becomes a laughing woman moving freely toward the horizon.",summaryZh:"克拉丽莎·平科拉·埃斯蒂斯在《与狼同行的女人》开篇提出了一个强烈的类比：女性与狼，都曾被恐惧、误解、驱赶，也都被迫退入越来越狭窄的领地。这本书把女性内部那种本能的、直觉的、创造性的、维持生命的力量称为“野性女人”。这里的“野性”并不是失控或鲁莽。它意味着依照更深层的完整性活着：感知危险、维护边界、进行创造、作出选择、知道何时离开、何时留下，也知道什么必须死去，什么必须继续活下去。在“狼女拉洛芭”的故事中，一位老妇人在沙漠里收集狼的骨头。当她拼出一副完整的骨架，她开始对着骨头歌唱。骨头长出血肉。身体开始呼吸。狼站起来，奔跑，并在途中变成一个大笑着冲向地平线的女人。",tags:["Wild Woman","instinct","intuition","bones","recovery","creativity","storytelling","boundaries","Life/Death/Life","women’s psychology"],status:"published"},{id:"2026-07-31-peggy-guggenheim-shock-of-the-modern",date:"2026-07-31",type:"book",title:"Peggy Guggenheim: The Shock of the Modern",titleZh:"《佩姬·古根海姆：现代性的震撼》",role:"Art Collecting / Patronage / Modernism｜艺术收藏 / 艺术赞助 / 现代主义",author:"Francine Prose｜弗朗辛·普罗斯",focusTitle:"How Does a Collector Enter Art History?",focusTitleZh:"收藏家如何进入艺术史？",summaryEn:"Peggy Guggenheim is often remembered through inherited wealth, unconventional relationships, and the famous artists around her. Francine Prose’s biography offers a more useful foundation: it presents Guggenheim as a woman who gradually learned how the modern art world worked, then used money, social networks, exhibitions, commissions, and institutional space to influence which artists became visible. Her importance does not lie simply in owning major works. She opened galleries, supported artists whose reputations were still uncertain, and converted private wealth into forms of public cultural influence. At the same time, her career remained marked by privilege, dependence on advisers, personal insecurity, and the unequal structures of the art world.",summaryZh:"佩姬·古根海姆经常因为继承财富、非常规的亲密关系，以及围绕在她身边的著名艺术家而被记住。弗朗辛·普罗斯的传记提供了一个更有解释力的基础：佩姬并不是天生拥有完美判断力的收藏家，而是在长期交往、学习与实践中理解现代艺术的运行方式，随后通过金钱、人际网络、展览、委托与机构空间，影响哪些艺术家能够进入公共视野。 她的重要性并不只是拥有大量名作。她开办画廊，支持尚未获得稳定声誉的艺术家，并把私人财富转化为公共文化影响力。与此同时，她的事业始终带有明显的矛盾：继承特权、对顾问的依赖、个人的不安全感，以及艺术世界本身的不平等结构。",highlightEn:"Peggy Guggenheim’s significance lies not only in what she collected, but in how she helped works and artists become visible.",highlightZh:"佩姬·古根海姆的重要性，不只在于她收藏了什么，也在于她如何帮助作品与艺术家变得可见。",sourceNote:"以上为日历编辑性概括，并非原书引文。",tags:["Peggy Guggenheim","art collecting","patronage","modernism","Jewish identity","cultural institutions","visibility","privilege","women and power","canon"],status:"published"},{id:"2026-08-01-sarah-waters-fingersmith",date:"2026-08-01",type:"novel",title:"Fingersmith",titleZh:"《指匠情挑》",role:"Novel / Neo-Victorian Fiction｜小说 / 新维多利亚主义文学",author:"Sarah Waters｜萨拉·沃特斯",focusTitle:"Who Has the Right to Write Desire?",focusTitleZh:"谁拥有书写欲望的权利？",summaryEn:"In Fingersmith, pornography is not treated simply as explicit sexual material. It is presented as a system of production, ownership, and interpretation in which men write women’s bodies, collect those representations, and control who is permitted to read them. Maud Lilly grows up inside her uncle’s library, where she is trained to catalogue pornographic books and read them aloud to male collectors. Her body, voice, literacy, and labour are all used to maintain a masculine archive from which she has no real authority to speak. The novel’s conclusion does not simply reject sexual writing. Instead, Maud becomes an author and writes erotic texts in her own name and for her own livelihood. Fingersmith therefore distinguishes between representations that reduce women to objects and writing through which women can claim desire, authorship, and economic agency. This distinction is central to feminist scholarship on the novel.",summaryZh:"在《指匠情挑》中，色情文本并不只是露骨的性描写。它首先是一套生产、占有与解释的制度：男性书写女性的身体，收藏这些表述，并控制谁有资格阅读它们。莫德·莉莉在舅舅的藏书室中长大。她被训练去整理色情书籍，并在男性收藏家面前朗读。她的身体、声音、识字能力与劳动，都被用来维持一个男性主导的档案体系，但她本人并没有真正的发言权。小说的结尾并没有简单否定性书写。相反，莫德成为作者，以写作获得收入，并开始用自己的语言处理女性欲望。因此，《指匠情挑》区分了两种不同的文本实践：一种把女性缩减为男性观看的对象，另一种让女性取得欲望、作者身份与经济行动力。相关女性主义研究也把这一转变视为小说的核心。",highlightEn:"The question is not whether women may write about sex. The question is who controls the language, the audience, and the meaning.",highlightZh:"问题并不是女性能否书写性。问题是：谁控制语言、读者与意义。",sourceNote:"以上为日历编辑性概括，并非原书引文。",tags:["female authorship","pornography","erotic writing","reading","literacy","lesbian history","book culture","consent","economic agency","neo-Victorian fiction"],status:"published"},{id:"2026-08-02-elise-hu-flawless",date:"2026-08-02",type:"book",title:"Flawless: Lessons in Looks and Culture from the K-Beauty Capital",titleZh:"《无瑕：来自 K-Beauty 之都的外貌与文化课》",role:"Beauty Culture / Lookism / Gendered Labour｜美容文化 / 外貌主义 / 性别化劳动",author:"Elise Hu｜胡伊莉丝",focusTitle:"When Does Self-Care Become Social Obligation?",focusTitleZh:"“自我护理”从什么时候开始变成社会义务？",summaryEn:"In Flawless, journalist Elise Hu examines South Korea’s beauty culture not as an isolated national curiosity, but as an intensified version of a global system. K-beauty offers pleasure, technical innovation, bodily care, and forms of self-expression. At the same time, the promise of improvement is tied to a demanding social environment in which appearance affects employment, relationships, status, and perceived moral worth. Hu’s central question is not whether skincare or makeup is inherently oppressive. She asks what happens when practices described as personal choice become difficult to refuse without economic and social consequences.",summaryZh:"在《无瑕》中，记者 Elise Hu 并没有把韩国美容文化写成一种孤立的国家奇观，而是把它视为全球外貌制度的强化版本。K-beauty 的确可以带来愉悦、技术创新、身体护理与自我表达。然而，“改善自己”的承诺也与一种严格的社会环境联系在一起：外貌会影响就业、亲密关系、社会地位，甚至一个人是否被看作自律、勤奋和体面。Hu 的核心问题并不是护肤或化妆本身是否具有压迫性。她追问的是：当一种被称为“个人选择”的实践，已经无法在不付出经济与社会代价的情况下被拒绝时，它还在多大程度上属于自由选择？",highlightEn:"Beauty work is presented as a choice, but the penalties for refusing it are not distributed equally.",highlightZh:"美容劳动被描述为一种选择，但拒绝它所付出的代价，并不是平等分配的。",sourceNote:"以上为日历编辑性概括，并非原书引文。",tags:["beauty culture","K-beauty","lookism","appearance labour","self-care","consumerism","technological gaze","gender inequality","Escape the Corset","body politics"],status:"published"},{id:"2026-08-03-naomi-wolf-the-beauty-myth",date:"2026-08-03",type:"book",title:"The Beauty Myth: How Images of Beauty Are Used Against Women",titleZh:"《美貌神话：美的形象如何被用来反对女性》",role:"Beauty Politics / Media / Labour｜美貌政治 / 媒体 / 劳动",author:"Naomi Wolf｜娜奥米·沃尔夫",focusTitle:"Beauty Is Not a Standard. It Is a System of Power.",focusTitleZh:"美貌不是一种标准，而是一套权力制度",summaryEn:"Naomi Wolf’s The Beauty Myth was first published in 1991. Its central argument is that beauty standards became more restrictive at the same historical moment when women gained greater access to education, employment, reproductive rights, and public authority. Wolf does not argue that beauty, cosmetics, fashion, or sexual attractiveness are inherently oppressive. In the 2002 introduction, she explicitly states that the issue is women’s right to decide how they want to look, rather than being required to obey standards created by advertising, commercial media, and the market. The beauty myth becomes political when appearance is treated as evidence of a woman’s discipline, professional competence, morality, sexuality, and social value. Under these conditions, women may formally possess more rights while still being required to devote extensive time, money, and attention to making themselves acceptable.",summaryZh:"娜奥米·沃尔夫的《美貌神话》初版于1991年。她的核心论点是：当女性逐渐取得教育、就业、生育权与公共权力时，社会对女性外貌的要求也变得更加严格。沃尔夫并不认为美、化妆、时尚或性吸引力本身必然具有压迫性。她在2002年版导言中明确指出，真正重要的是女性能否决定自己想要怎样的外表，而不是服从广告、商业媒体与市场规定的形象。当外貌被用来判断一个女人是否自律、是否具有职业能力、是否体面、是否具有性价值时，美貌神话便成为政治问题。在这种制度下，女性可能在形式上拥有更多权利，却仍要投入大量时间、金钱与注意力，使自己变得“可以被接受”。",highlightEn:"The beauty myth does not simply tell women how to look. It influences what women believe they are entitled to do.",highlightZh:"美貌神话不只规定女性应该怎样看起来，也影响女性认为自己有权做什么。",tags:["beauty myth","appearance labour","media","advertising","workplace discrimination","consumerism","body politics","female solidarity","choice","institutional power"],status:"published"},{id:"2026-08-04-nikki-khanna-whiter",date:"2026-08-04",type:"book",title:"Whiter: Asian American Women on Skin Color and Colorism",titleZh:"《更白：亚裔美国女性的肤色与肤色主义》",role:"Colorism / Asian American Studies / Gender｜肤色主义 / 亚裔美国研究 / 性别",author:"Nikki Khanna｜妮基·卡纳",focusTitle:"When Skin Color Becomes Social Value",focusTitleZh:"当肤色被换算成社会价值",summaryEn:"In Whiter, sociologist Nikki Khanna brings together the personal narratives of Asian American women from different ethnic, racial, and generational backgrounds. The book examines colorism: discrimination that privileges lighter skin over darker skin, both within racial communities and across racial and ethnic groups. For the women in the book, skin color is rarely treated as a neutral physical characteristic. It is connected to beauty, femininity, class, intelligence, marriageability, professional opportunity, national belonging, and assumptions about who is truly American. Khanna shows that colorism is not simply a private preference for a particular complexion. It is a hierarchy shaped by racism, colonial history, class relations, anti-Blackness, media representation, and gendered expectations.",summaryZh:"在《更白》中，社会学家 Nikki Khanna 收录了来自不同族裔、种族与世代背景的亚裔美国女性的个人叙述。这本书讨论的是肤色主义：一种在同一种族群体内部，以及不同种族和族裔之间，赋予浅色皮肤更多价值、歧视深色皮肤的制度。对书中的女性而言，肤色很少只是一项中性的身体特征。它与美貌、女性气质、阶级、智力、婚姻价值、职业机会和国家归属联系在一起，并影响谁会被承认为“真正的美国人”。Khanna 所揭示的肤色主义，并不只是个人对某种肤色的偏好。它是一套由种族主义、殖民历史、阶级关系、反黑人观念、媒体再现与性别规范共同塑造的等级制度。",highlightEn:"Skin color does not merely affect how a woman is seen. It can influence whether she is considered beautiful, respectable, successful, or entitled to belong.",highlightZh:"肤色不仅影响一个女人如何被观看，也可能影响她是否被认为美丽、体面、成功，以及是否有资格归属于某个群体。",tags:["colorism","Asian American women","skin whitening","whiteness","colonialism","gendered colorism","anti-Blackness","social class","belonging","self-acceptance"],status:"published"},{id:"2026-08-05-alice-guy-blache-be-natural",date:"2026-08-05",type:"film",title:"Alice Guy-Blaché",titleZh:"爱丽丝·居伊-布拉谢",years:"1873–1968",role:"Early Cinema / Directing / Film History｜早期电影 / 导演 / 电影史",creator:"Alice Guy-Blaché",creatorZh:"爱丽丝·居伊-布拉谢",focusTitle:"Who Was Written Out of the Beginning of Cinema?",focusTitleZh:"谁被排除在电影的起源叙事之外？",summaryEn:"Alice Guy-Blaché was the first woman known to build a sustained professional career as a film director. She proposed that film could do more than record movement: it could stage fictional situations, direct performers, and tell stories.",summaryZh:"爱丽丝·居伊-布拉谢是目前所知第一位以电影导演为持续职业的女性。她提出，电影不必只记录运动，也可以设计虚构情境、指导演员并讲述故事。",tags:["Alice Guy-Blaché","early cinema","women directors","film authorship","Solax","Gaumont","silent film","film preservation","archival erasure","women and institutions"],status:"published"},{id:"2026-08-06-jeanette-winterson-oranges",date:"2026-08-06",type:"novel",title:"Oranges Are Not the Only Fruit",titleZh:"《橘子不是唯一的水果》",years:"b. 1959",role:"Novel / Queer Literature / Biblical Rewriting｜小说 / 酷儿文学 /《圣经》重写",creator:"Jeanette Winterson",creatorZh:"珍妮特·温特森",focusTitle:"Who Decides What Counts as the Only Truth?",focusTitleZh:"是谁决定，世界只有一种真理？",summaryEn:`Jeanette is adopted by a devout Pentecostal mother who believes her daughter has been chosen for missionary work. The child learns to interpret life through sermons, biblical stories, hymns, spiritual warfare, and the absolute division between the saved and the unsaved.

This system gives Jeanette a language, a community, and a public voice. The conflict begins when she falls in love with another young woman. Her church declares that love incompatible with faith and interprets it as evidence of demonic influence.

The novel does not simply oppose religion with freedom. Jeanette begins to distinguish faith from the people who claim exclusive authority to interpret it. The question is not whether stories shape our lives, but whether one institution has the right to control every story's meaning.`,summaryZh:`珍妮特被一位虔诚的五旬节派母亲收养。母亲相信这个女儿是上帝赐予她的礼物，并计划把她培养成传教士。这个女孩通过布道、《圣经》故事、赞美诗与属灵争战理解世界，也接受了一套泾渭分明的分类：得救与未得救、朋友与敌人、神圣与邪恶。

这套信仰体系给予珍妮特语言、共同体与公开发言的机会。冲突发生在她爱上另一个年轻女人之后。教会认定这种爱情与信仰不能共存，并把它解释成邪灵作祟的证据。

小说并没有简单地把宗教与自由写成对立面。珍妮特逐渐区分信仰本身与那些声称垄断解释权的人。小说真正追问的不是故事是否塑造人生，而是某个机构是否有权决定所有故事只能具有一种意义。`,highlightEn:"Oranges are not the only fruit.",highlightZh:"橘子不是唯一的水果。",tags:["queer literature","biblical rewriting","interpretive authority","lesbian desire","faith","storytelling","chosen kinship","female authorship"],status:"published"},{id:"2026-08-07-angela-nikolau-skywalkers",date:"2026-08-07",type:"artist",title:"Skywalkers: A Love Story",titleZh:"《天行者：爱情故事》",role:"Visual Art / Photography / Performance｜视觉艺术 / 摄影 / 行为表演",creator:"Angela Nikolau",creatorZh:"安吉拉·尼古拉乌",focusTitle:"Calling for Love at the Top of the World",focusTitleZh:"在世界的顶端呼唤爱",summaryEn:`Angela Nikolau is a visual artist whose practice combines photography, bodily performance, urban exploration, architecture, and digital circulation. She is known for images made on rooftops, cranes, towers, and other restricted high-rise structures. In her current public profile, she describes her work as an exploration of identity, fear, and freedom.

The 2024 documentary Skywalkers: A Love Story follows Nikolau and Ivan Beerkus over several years as their artistic partnership develops into a romantic relationship. Its central sequence records their unauthorised ascent of Merdeka 118 in Kuala Lumpur, where they prepare and perform an acrobatic pose near the building's spire.

In July 2026, their relationship and artistic practice entered a new public phase when they climbed the Empire State Building's antenna without authorisation. At the top, they displayed a banner about love and peace. They then descended to a lower ledge, where Beerkus proposed to Nikolau.`,summaryZh:`Angela Nikolau 是一位视觉艺术家。她的实践结合摄影、身体表演、城市探索、建筑空间与数字传播。她因在屋顶、塔吊、高塔及其他受限制的高层建筑上创作图像而受到关注。她目前在公开简介中把自己的创作概括为对身份、恐惧与自由的探索。

2024年的纪录片《天行者：爱情故事》跨越数年，记录 Nikolau 与 Ivan Beerkus 的艺术合作如何发展为亲密关系。影片的核心段落是两人未经许可攀登吉隆坡默迪卡118，并在接近大楼尖顶的位置准备和完成一个杂技式动作。

2026年7月，两人的关系与艺术实践以一种新的方式进入公共视野。他们未经许可攀上帝国大厦天线，在顶部展开一条关于爱与和平的横幅，随后下降到较低的平台，由 Beerkus 向 Nikolau 求婚。`,highlightEn:"At extreme height, trust becomes part of the work's physical structure.",highlightZh:"在极端高度上，信任成为作品物理结构的一部分。",tags:["visual art","photography","performance","urban exploration","architecture","fear","freedom","trust","digital circulation"],image:"/A-Calendar-of-Her-Own/images/angela-nikolau-empire-state-close.png",imageCredit:"User-provided image｜用户上传图片",status:"published"},{id:"2026-08-08-sally-rooney-class-intimacy",date:"2026-08-08",type:"writer",title:"Sally Rooney",titleZh:"萨莉·鲁尼",years:"b. 1991",role:"Novel / Class / Intimacy｜小说 / 阶级 / 亲密关系",focusTitle:"How Does Class Enter a Relationship?",focusTitleZh:"阶级如何进入一段关系？",summaryEn:`Sally Rooney's novels are often described as stories about love, sex, friendship, and failed communication. But across her four published novels, class is just as important as desire. Money, housing, education, occupation, family background, and social confidence continually affect what her characters can ask from one another, what they can refuse, and what they are ashamed to admit.

Scholarship on Conversations with Friends and Normal People has placed their characters within post-crash Ireland and examined how neoliberal individualism, class inequality, vulnerability, and dependence shape emotional life.

Pierre Bourdieu gives us a useful language for understanding why Rooney's class writing cannot be reduced to income. Her characters may attend the same university, read the same books, or know the same political vocabulary while possessing very different combinations of economic, cultural, and social capital.`,summaryZh:`萨莉·鲁尼的小说经常被概括为关于爱情、性、友谊与沟通失败的故事。但纵观她目前出版的四部长篇，阶级与欲望同样重要。金钱、住房、教育、职业、家庭背景，以及一个人在特定社会环境中的自在程度，不断影响着人物能够向另一个人提出什么要求、能够拒绝什么，也影响着哪些需要会因为羞耻而无法说出口。

关于《聊天记录》与《正常人》的学术研究已经把人物放回金融危机后的爱尔兰社会中，讨论新自由主义个人主义、阶级不平等、脆弱性与依赖如何进入情感生活。

Pierre Bourdieu 的理论可以帮助我们理解，为什么 Rooney 笔下的阶级不能被简单缩减为收入差距。她的人物完全可能进入同一所大学、阅读相同的书、使用相同的政治语言，却拥有截然不同的经济资本、文化资本与社会资本组合。`,highlightEn:"People may appear to belong to the same cultural world while inhabiting it under very different material conditions. Class enters intimacy through these differences.",highlightZh:"几个人看起来属于同一个文化世界，却并不以相同的物质条件生活在其中。阶级正是通过这些差异进入亲密关系。",tags:["class","intimacy","economic capital","cultural capital","housing","vulnerability","care","neoliberalism","Irish fiction"],status:"published"},{id:"2026-08-09-george-eliot-middlemarch",date:"2026-08-09",type:"novel",title:"Middlemarch: A Study of Provincial Life",titleZh:"《米德尔马契》",years:"1819–1880",role:"Novel｜小说 / Realism｜现实主义 / Women and Vocation｜女性与志业",creator:"George Eliot",creatorZh:"乔治·艾略特",focusTitle:"What Does a Woman Do with Her Ability?",focusTitleZh:"一个有能力的女人，如何安放自己的才能？",summaryEn:"George Eliot's Middlemarch begins with a woman who wants more from life than marriage. Dorothea Brooke is intelligent, morally serious, and eager to devote herself to work that matters. Yet the society around her offers few recognised forms through which a woman like her can turn ability into vocation.",summaryZh:"乔治·艾略特的《米德尔马契》从一个不满足于婚姻的女性开始。多萝西娅·布鲁克聪慧、认真，也强烈希望把自己的生命投入有意义的事业。但她所处的社会几乎没有为这样的女性提供把能力转化为志业的正式路径。",tags:["vocation","women and work","intellectual life","marriage","institutions","realism","female authority","George Eliot"],status:"published"},{id:"2026-08-10-anne-anlin-cheng-ornamentalism",date:"2026-08-10",type:"theory",title:"Anna May Wong, Chinatown, and the “Yellow Woman”: Who Made the Asian Woman?",titleZh:"黄柳霜、唐人街与“黄种女人”：谁制造了亚裔女性？",role:"Feminist Theory｜女性主义理论 / Asian American Studies｜亚裔美国研究",creator:"Anne Anlin Cheng",focusTitle:"Ornamentalism",focusTitleZh:"《装饰主义》（暂译）",summaryEn:"Anne Anlin Cheng's Ornamentalism asks how Asiatic femininity has been made through beauty, surface, ornament, and synthetic objects. The book shows that aesthetic admiration and racial violence do not always oppose one another: a person may be prized as an image while being denied full personhood.",summaryZh:"Anne Anlin Cheng 的《装饰主义》追问：亚裔女性气质如何通过美、表面、装饰与人造物被生产出来。书中指出，审美欣赏与种族暴力并不总是彼此对立：一个人可能作为图像受到珍爱，却同时被拒绝完整的人格。",tags:["ornamentalism","Asian femininity","race","aesthetics","objecthood","synthetic personhood","beauty","visual culture","feminist theory"],status:"published"},{id:"2026-08-11-laura-bates-the-new-age-of-sexism",date:"2026-08-11",type:"book",title:"The New Age of Sexism",titleZh:"《性别歧视的新时代》（暂译）",years:"2025",role:"Book｜著作 / Feminist Technology Criticism｜女性主义技术批评",creator:"Laura Bates",creatorZh:"劳拉·贝茨",focusTitle:"Who Is the Future Being Built For?",focusTitleZh:"未来究竟为谁而建？",summaryEn:"New technologies do not arrive outside society. Laura Bates shows how deepfakes, virtual worlds, AI companions, and automated systems can reproduce and intensify old misogyny when speed and profit are placed before safety and equality.",summaryZh:"新技术并不是在社会之外降临。Laura Bates 指出，当速度与利润被置于安全和平等之前，深度伪造、虚拟世界、AI 伴侣与自动化系统可能复制并强化旧有的厌女结构。",tags:["artificial intelligence","misogyny","deepfakes","digital violence","algorithmic bias","technology","safety by design","feminist technology"],status:"published"},{id:"2026-08-12-a-history-of-witchcraft",date:"2026-08-12",type:"book",title:"A History of Witchcraft: Sorcerers, Heretics & Pagans",titleZh:"《巫术史：术士、异端与异教徒》（暂译）",years:"2024 revised edition",role:"History｜历史 / Witchcraft Studies｜巫术研究",creator:"Jeffrey B. Russell and Brooks Alexander",focusTitle:"Who Was Made into a Witch?",focusTitleZh:"谁被制造成“女巫”？",summaryEn:"The history of witchcraft is not the history of one timeless, secret identity. It is a history of changing definitions, social fear, religious demonology, legal power, and accusation. Women became the majority of the accused not because witchcraft was naturally female, but because misogyny and social vulnerability made certain women easier to suspect and punish.",summaryZh:"巫术史并不是某种永恒秘密身份的历史，而是一部关于定义如何变化、恐惧如何扩散、宗教如何制造恶魔、法律如何行使权力，以及指控如何形成的历史。女性成为被告中的多数，并不是因为巫术天然属于女性，而是因为厌女观念与社会弱势让某些女性更容易被怀疑和惩罚。",tags:["witchcraft","witch hunts","misogyny","accusation","social vulnerability","religion","law","Neopaganism"],status:"published"},{id:"2026-08-13-mrs-dalloway",date:"2026-08-13",type:"novel",title:"Mrs Dalloway",titleZh:"《达洛维夫人》",years:"1925",role:"Novel｜小说 / Modernism｜现代主义 / Domesticity｜家庭生活 / Social Labour｜社会劳动",creator:"Virginia Woolf",creatorZh:"弗吉尼亚·伍尔夫",focusTitle:"The Work of the Perfect Hostess",focusTitleZh:"“完美女主人”的劳动",summaryEn:`Clarissa Dalloway spends one June day preparing an evening party. She buys flowers, considers the guest list, repairs her dress, receives visitors, and worries whether the gathering will succeed. These activities are easily dismissed as the trivial preoccupations of a politician's wife. Virginia Woolf instead enters Clarissa's consciousness and asks what kind of work is hidden inside the role of the “perfect hostess.”

Clarissa's party is both personal and political. It is her attempt to bring separated lives into one room, but it also sustains the social world of her husband, Richard, and the governing class to which they belong. Her work creates connection, atmosphere, and recognition without receiving the name of a profession.

The novel also prevents us from treating Clarissa as the only woman working in the house. Her freedom to walk through London and imagine the party as her creative gift depends on servants whose cooking, cleaning, carrying, dressing, and door-keeping make the evening possible. A feminist reading of the housewife must therefore keep gender and class in the same frame.`,summaryZh:`克拉丽莎·达洛维用六月里的一天准备晚间宴会。她购买鲜花、考虑宾客名单、缝补礼服、接待来客，也担心聚会能否成功。这些活动很容易被视为一位政治家妻子的琐碎事务。弗吉尼亚·伍尔夫却进入克拉丽莎的意识，追问“完美女主人”这个角色隐藏了怎样的劳动。

克拉丽莎的宴会既是私人活动，也是政治活动。她试图把彼此分离的生命带进同一个房间，而聚会同时维系了丈夫理查德及其所属统治阶层的社交世界。她制造联系、气氛与相互承认，这些工作却没有获得职业的名称。

小说也阻止我们把克拉丽莎当作这所房子里唯一劳动的女人。她能够走上伦敦街头，并把宴会想象成自己的创造性赠礼，是因为佣人承担了烹饪、清洁、搬运、协助穿衣与看门等工作。对家庭主妇的女性主义阅读，因此必须把性别与阶级放在同一个画面里。`,tags:["Virginia Woolf","Mrs Dalloway","domesticity","social labour","hostess","class","modernism"],status:"published"},{id:"2026-08-14-the-penelopiad",date:"2026-08-14",type:"novel",title:"The Penelopiad",titleZh:"《珀涅罗珀记》",years:"2005",role:"Novel｜小说 / Myth Retelling｜神话重写 / Feminist Revision｜女性主义修订 / Chorus｜合唱队",creator:"Margaret Atwood",creatorZh:"玛格丽特·阿特伍德",focusTitle:"Whose Voice Survives the Hero's Story?",focusTitleZh:"英雄故事结束后，谁的声音能够留下？",summaryEn:`In The Penelopiad, Margaret Atwood retells The Odyssey from the underworld. Penelope finally speaks after centuries of being remembered as the faithful wife who waited, wove, and endured. But she is not the only one who returns. The twelve maids hanged after Odysseus's homecoming interrupt her story with songs, accusations, jokes, and demands for justice.

Penelope revises the legend that turned her into a model for other women. Yet the maids also question her version. They were enslaved girls who worked, carried messages, endured sexual coercion, and helped protect their mistress's household. Their chorus asks whether giving one privileged woman a voice is enough when poorer women remain unnamed.

Atwood's feminist rewriting does not simply replace a male hero with a flawless female heroine. It asks who owns a story, whose labour supports the household, whose suffering becomes a symbol, and whose death can be excused as the custom of another age.`,summaryZh:`在《珀涅罗珀记》中，玛格丽特·阿特伍德让《奥德赛》的故事从冥界重新开始。几个世纪以来，珀涅罗珀一直被记作那个忠贞等待、不断织布并默默忍耐的妻子；如今，她终于获得讲述自己的机会。但回来的并不只有她。奥德修斯返乡后被绞死的十二名女仆，以歌唱、控诉、讽刺与对正义的要求，不断打断她的故事。

珀涅罗珀修订了那个把她塑造成女性典范的传说，但女仆们也在质疑她的版本。她们是被奴役的女孩，承担劳动、传递消息、遭受性胁迫，也曾帮助女主人保护家宅。她们的合唱追问：如果较贫穷的女性仍然没有名字，那么只让一位拥有特权的女性发声，真的足够吗？

阿特伍德的女性主义重写，并不是用一位完美女主人公替换男性英雄。它追问谁拥有故事，谁的劳动支撑家庭，谁的痛苦被转换成象征，又是谁的死亡可以被“另一个时代的习俗”轻易解释过去。`,tags:["Margaret Atwood","The Penelopiad","myth retelling","maids","class","slavery","female authorship"],status:"published"},{id:"2026-08-15-cleo-from-5-to-7",date:"2026-08-15",type:"film",title:"Cléo from 5 to 7",titleZh:"《五至七时的克莱奥》",years:"1962",role:"Film｜电影 / French New Wave｜法国新浪潮 / Feminist Cinema｜女性主义电影 / Time｜时间",creator:"Agnès Varda",creatorZh:"阿涅斯·瓦尔达",focusTitle:"From Being Looked At to Looking at the World",focusTitleZh:"从被观看，到观看世界",summaryEn:`Cléo is a young singer waiting for the results of a medical examination. For ninety minutes, she moves through Paris among mirrors, hats, cafés, songs, taxis, strangers, friends, and street noise. At first, she tries to manage fear by confirming that she is still beautiful. If her image remains intact, perhaps death can be kept at a distance.

But Agnès Varda gradually changes the direction of vision. Cléo removes the blonde wig that helps compose her public image, leaves the people who infantilise her, and walks alone. The city is no longer only a stage on which she is seen. She begins to notice faces, bodies, labour, danger, illness, war, and lives continuing beside her own.

The film does not present this change as a complete escape from fear or from other people's gaze. Cléo is still frightened, still visible, and still vulnerable. What changes is her relation to the world: she becomes capable of looking outward and of meeting another person without performing the role of “Cléo” quite so completely.`,summaryZh:`克莱奥是一位等待医学检查结果的年轻歌手。在九十分钟里，她穿过巴黎的镜子、帽子店、咖啡馆、歌曲、出租车、陌生人、朋友与街道噪音。最初，她试图通过确认自己仍然美丽来控制恐惧：只要镜中的形象没有破裂，死亡似乎就还能被推远。

但阿涅斯·瓦尔达逐渐改变了观看的方向。克莱奥摘下构成她公众形象的金色假发，离开那些把她当作孩子的人，独自走上街头。城市不再只是供她被观看的舞台。她开始注意面孔、身体、劳动、危险、疾病、战争，以及与她的生命并行发生的其他人生。

影片没有把这种变化写成对恐惧或他人目光的彻底逃离。克莱奥依然害怕，依然处于可见状态，也依然脆弱。真正改变的是她与世界的关系：她开始能够向外观看，也开始能够在不完全表演“克莱奥”这个角色的情况下与另一个人相遇。`,tags:["Agnès Varda","Cléo from 5 to 7","French New Wave","female subjectivity","gaze","time","Paris","illness"],status:"published"}];function m(e){const i=e.getFullYear(),a=String(e.getMonth()+1).padStart(2,"0"),s=String(e.getDate()).padStart(2,"0");return`${i}-${a}-${s}`}function y(e){const[i,a]=(e==null?void 0:e.split("｜"))??[];return{en:i==null?void 0:i.trim(),zh:a==null?void 0:a.trim()}}function g(e){const i=y(e.author);return{id:e.id,date:e.date,cardType:e.type,cardTitle:e.title,cardTitleZh:e.titleZh,years:e.years,role:e.role,creator:e.creator??i.en,creatorZh:e.creatorZh??i.zh,focusTitle:e.focusTitle,focusTitleZh:e.focusTitleZh,thinkerId:e.personId??e.id,thinkerName:e.creator??i.en??e.title,thinkerNameZh:e.creatorZh??i.zh??e.titleZh??e.title,birthDeath:e.years??e.date,concept:e.focusTitle??e.title,conceptZh:e.focusTitleZh??e.titleZh??e.title,tags:e.tags,quote:"",quoteSource:"",explanationEn:e.summaryEn??"",explanationZh:e.summaryZh??"",highlightEn:e.highlightEn,highlightZh:e.highlightZh,sourceNote:e.sourceNote,reflectionQuestion:"",relatedWorks:[],personId:e.personId,image:e.image,imageCredit:e.imageCredit}}function p(e=m(new Date)){const i=d.filter(o=>o.status==="published"&&o.date<=e).sort((o,n)=>o.date.localeCompare(n.date)),s=i.find(o=>o.date===e)??i[i.length-1];return s?g(s):void 0}function T(){const e=p();return t.jsxs("div",{className:"home-page",children:[t.jsxs("header",{className:"home-hero",children:[t.jsx("p",{className:"home-hero__spark",children:"A Calendar of Her Own ✦ 她自己的日历"}),t.jsx("p",{children:"读女性如何理解世界。"})]}),e?t.jsxs(t.Fragment,{children:[t.jsx(c,{date:e.date}),t.jsxs("div",{className:"calendar-card-divider","aria-hidden":"true",children:[t.jsx("span",{}),t.jsx("b",{children:"✦"}),t.jsx("span",{})]}),t.jsx(h,{card:e,mode:"today"})]}):t.jsx(l,{title:"还没有发布卡片",description:"在 dailyCards.ts 中添加 status 为 published 的每日卡片后，这里会自动显示。"}),t.jsx(u,{})]})}export{T as default};
